import { spawnSync } from 'node:child_process';
import path from 'node:path';

function npmCmd() { return process.platform === 'win32' ? 'npm.cmd' : 'npm'; }
function runCmd(command, args, cwd, timeout) {
  const r = spawnSync(command, args, { cwd, encoding: 'utf8', timeout, shell: false });
  return { command: [command, ...args].join(' '), status: r.status, stdout: r.stdout, stderr: r.stderr, timedOut: Boolean(r.error && /timed out/i.test(r.error.message)), ok: r.status === 0 };
}

export async function run(input = {}) {
  const projectRoot = input.projectRoot || 'E:\\quant-framework';
  const pytest = runCmd('python', ['-m', 'pytest', 'tests/contracts', '-q'], projectRoot, 120000);
  let frontendBuild = { skipped: true, ok: true };
  if (input.runFrontendBuild !== false) {
    frontendBuild = runCmd(npmCmd(), ['--prefix', 'dashboard/frontend', 'run', 'build'], projectRoot, 180000);
  }
  return { ok: Boolean(pytest.ok && frontendBuild.ok), pytest, frontendBuild };
}
